export const PreviewAssessmentResponse = zod.object({
  "schemaVersion": zod.string(),
  "asOfDate": zod.string(),
  "rulesetVersion": zod.string(),
  "items": zod.array(zod.object({
  "ruleId": zod.string(),
  "ruleVersion": zod.int(),
  "requirementVersionId": zod.string(),
  "title": zod.string(),
  "label": zod.enum(['Likely relevant', 'May apply', 'More information needed', 'Not indicated by these answers']),
  "reason": zod.string(),
  "assessedProposition": zod.string().optional(),
  "factsNotice": zod.string().optional(),
  "sourceReviewHold": zod.string().optional(),
  "releaseNotice": zod.string().optional().describe('How the rule behind this item was released (EDP-008). A result saved before the notice was recorded has none.'),
  "sourceLinkedTaskEligible": zod.boolean().optional(),
  "missingAnswerStates": zod.array(zod.object({
  "field": zod.string(),
  "state": zod.enum(['unknown', 'unanswered', 'not_applicable', 'review'])
})).optional(),
  "missingFacts": zod.array(zod.string()),
  "matchedFacts": zod.array(zod.string()),
  "nextStep": zod.string(),
  "jurisdiction": zod.object({
  "level": zod.enum(['federal', 'state', 'lga']),
  "state": zod.string().optional(),
  "lga": zod.string().optional()
}),
  "sources": zod.array(zod.object({
  "id": zod.string(),
  "url": zod.string(),
  "title": zod.string(),
  "locator": zod.string(),
  "quote": zod.string(),
  "snapshotHash": zod.string()
})),
  "relatedTemplateIds": zod.array(zod.string()),
  "officialRoute": zod.object({
  "authority": zod.string(),
  "url": zod.string()
}).optional().describe('The authority\'s own official page for a requirement, as its rule records it. Absent when the rule records none, and in a result saved before routes were recorded.'),
  "figures": zod.array(zod.object({
  "kind": zod.enum(['fee', 'deadline', 'rate', 'threshold']),
  "words": zod.string().describe('In the words of the passage of the item\'s source it rests on.'),
  "sourceId": zod.string().describe('The id of one of the item\'s sources.')
})).optional().describe('Each fee, deadline, rate or threshold the item\'s rule records, with the source it rests on (CMP-006). Absent when the rule records none, and in a result saved before figures were recorded.'),
  "sourceCheckedAt": zod.string().optional().describe('When the rule\'s sources were last checked (CMP-004). Absent in a result saved before dates were recorded.'),
  "publication": zod.object({
  "route": zod.enum(['owner_signoff', 'editorial_release']),
  "publishedAt": zod.string()
}).optional().describe('How the rule was released and when, from its release record (CMP-004). Absent for a test rule, and in a result saved before dates were recorded.')
})),
  "unanswered": zod.array(zod.string()),
  "gaps": zod.array(zod.string()),
  "recommendedTemplateIds": zod.array(zod.string()),
  "officialRoutes": zod.array(zod.object({
  "title": zod.string(),
  "url": zod.string()
})),
  "notice": zod.string(),
  "sourceBackedRecommendations": zod.int(),
  "resultHash": zod.string()
})


/**
 * The released rules the requirements check would use today, under the same release checks as an assessment, and which of the check's rule questions each reads (RUL-001). Holds no customer data. Counts against the per-visitor limit on public reads.
 */
export const ListCheckerRulesInUseResponse = zod.object({
  "asOfDate": zod.string(),
  "rules": zod.array(zod.object({
  "ruleId": zod.string(),
  "ruleVersion": zod.int(),
  "title": zod.string(),
  "family": zod.union([zod.literal('businessName'),zod.literal('tax'),zod.literal('privacy'),zod.literal('product'),zod.literal(null)]).nullable().describe('The rule questions the rule reads, or null for a rule that reads only the check\'s own questions.')
}))
})


